interface SortStrategy { void sort(int[] arr); }

class AscendingSort implements SortStrategy {
    public void sort(int[] arr) { java.util.Arrays.sort(arr); }
}
class DescendingSort implements SortStrategy {
    public void sort(int[] arr) {
        java.util.Arrays.sort(arr);
        for (int i = 0; i < arr.length / 2; i++) {
            int t = arr[i]; arr[i] = arr[arr.length - 1 - i]; arr[arr.length - 1 - i] = t;
        }
    }
}

class NumberSorter {
    private SortStrategy strategy;
    void setStrategy(SortStrategy s) { this.strategy = s; }
    void sort(int[] arr) { strategy.sort(arr); }
}

