import java.util.Stack;

interface Command { void execute(); void undo(); }

class TextEditor { StringBuilder content = new StringBuilder(); }

class TypeCommand implements Command {
    private TextEditor editor; private String text;
    TypeCommand(TextEditor editor, String text) { this.editor = editor; this.text = text; }
    public void execute() { editor.content.append(text); }
    public void undo() { editor.content.setLength(editor.content.length() - text.length()); }
}

class DeleteCommand implements Command {
    private TextEditor editor; private int count; private String deleted;
    DeleteCommand(TextEditor editor, int count) { this.editor = editor; this.count = count; }
    public void execute() {
        int len = editor.content.length();
        deleted = editor.content.substring(len - count);
        editor.content.setLength(len - count);
    }
    public void undo() { editor.content.append(deleted); }
}

class CommandHistory {
    private Stack<Command> undoStack = new Stack<>();
    void execute(Command c) { c.execute(); undoStack.push(c); }
    void undo() { if (!undoStack.isEmpty()) undoStack.pop().undo(); }
}

TextEditor editor = new TextEditor();
CommandHistory history = new CommandHistory();
history.execute(new TypeCommand(editor, "Hello"));
history.execute(new TypeCommand(editor, " World"));
history.execute(new DeleteCommand(editor, 5));
System.out.println(editor.content);
history.undo();
System.out.println(editor.content);
