interface ShapeVisitor {
    double visitCircle(double r);
    double visitRectangle(double w, double h);
}

interface Shape { double accept(ShapeVisitor v); }

class Circle implements Shape {
    double r; Circle(double r) { this.r = r; }
    public double accept(ShapeVisitor v) { return v.visitCircle(r); }
}
class Rectangle implements Shape {
    double w, h; Rectangle(double w, double h) { this.w = w; this.h = h; }
    public double accept(ShapeVisitor v) { return v.visitRectangle(w, h); }
}

class AreaVisitor implements ShapeVisitor {
    public double visitCircle(double r) { return Math.PI * r * r; }
    public double visitRectangle(double w, double h) { return w * h; }
}
class PerimeterVisitor implements ShapeVisitor {
    public double visitCircle(double r) { return 2 * Math.PI * r; }
    public double visitRectangle(double w, double h) { return 2 * (w + h); }
}

Shape[] shapes = { new Circle(5), new Rectangle(4, 6) };
ShapeVisitor area = new AreaVisitor();
ShapeVisitor perimeter = new PerimeterVisitor();
for (Shape s : shapes) {
    System.out.println("Pole: " + s.accept(area));
    System.out.println("Obwod: " + s.accept(perimeter));
}

