    new AddExpression(new NumberExpression(3), new NumberExpression(4)),
    new SubtractExpression(new NumberExpression(10), new NumberExpression(6))
);
System.out.println(expr.interpret());

import java.util.HashMap;
import java.util.Map;

record FontStyle(String font, int size, boolean bold, boolean italic) {}

class FontStyleFactory {
    private static Map<String, FontStyle> cache = new HashMap<>();

    static FontStyle getFontStyle(String font, int size, boolean bold, boolean italic) {
        String key = font + size + bold + italic;
        return cache.computeIfAbsent(key, k -> new FontStyle(font, size, bold, italic));
    }
}

java.util.Random rnd = new java.util.Random(1);
String[] fonts = {"Arial", "Times"};
for (int i = 0; i < 1000; i++) {
    FontStyleFactory.getFontStyle(fonts[rnd.nextInt(2)], 12 + rnd.nextInt(3), rnd.nextBoolean(), rnd.nextBoolean());
}
System.out.println("Utworzono " + 1000 + " czcionek, unikalnych obiektow: (sprawdz rozmiar cache)");

import java.util.Stack;

record TextMemento(String content) {}

class TextEditor {
    private StringBuilder content = new StringBuilder();
    private Stack<TextMemento> history = new Stack<>();

    void type(String text) { content.append(text); }
    void save() { history.push(new TextMemento(content.toString())); }
    void restore(TextMemento m) { content = new StringBuilder(m.content()); }
    void undo() { if (!history.isEmpty()) restore(history.pop()); }
    String getContent() { return content.toString(); }
}

TextEditor editor = new TextEditor();
editor.type("Hello");
editor.save();
editor.type(" World");
editor.type("!");
System.out.println("Przed undo: " + editor.getContent());
editor.undo();
System.out.println("Po undo: " + editor.getContent());

interface Renderer {
    void renderCircle(double r);
    void renderRect(double w, double h);
}

class VectorRenderer implements Renderer {
    public void renderCircle(double r) { System.out.println("Wektorowe kolo r=" + r); }
    public void renderRect(double w, double h) { System.out.println("Wektorowy prostokat " + w + "x" + h); }
}
class RasterRenderer implements Renderer {
    public void renderCircle(double r) { System.out.println("Rastrowe kolo r=" + r); }
    public void renderRect(double w, double h) { System.out.println("Rastrowy prostokat " + w + "x" + h); }
}

abstract class Shape {
    protected Renderer renderer;
    Shape(Renderer renderer) { this.renderer = renderer; }
    abstract void draw();
}

class Circle extends Shape {
    private double radius;
    Circle(Renderer renderer, double radius) { super(renderer); this.radius = radius; }
    void draw() { renderer.renderCircle(radius); }
}
class Rectangle extends Shape {
    private double w, h;
    Rectangle(Renderer renderer, double w, double h) { super(renderer); this.w = w; this.h = h; }
    void draw() { renderer.renderRect(w, h); }
}

new Circle(new VectorRenderer(), 5).draw();
new Circle(new RasterRenderer(), 5).draw();
new Rectangle(new VectorRenderer(), 3, 4).draw();
new Rectangle(new RasterRenderer(), 3, 4).draw();

import java.util.ArrayList;
import java.util.List;

record Order(String product, int quantity, String deliveryMethod) {}

class OrderBuilder {
    private String product; private int quantity; private String deliveryMethod = "Standard";
    OrderBuilder product(String p) { this.product = p; return this; }
    OrderBuilder quantity(int q) { this.quantity = q; return this; }
    OrderBuilder delivery(String d) { this.deliveryMethod = d; return this; }
    Order build() { return new Order(product, quantity, deliveryMethod); }
}

interface OrderObserver { void onStatusChange(String status); }

class OrderTracker {
    private List<OrderObserver> observers = new ArrayList<>();
    void addObserver(OrderObserver o) { observers.add(o); }
    void updateStatus(String status) { for (OrderObserver o : observers) o.onStatusChange(status); }
}

Order order = new OrderBuilder().product("Laptop").quantity(1).delivery("Express").build();
System.out.println("Zamowienie: " + order);

OrderTracker tracker = new OrderTracker();
tracker.addObserver(status -> System.out.println("Powiadomienie: " + status));
tracker.updateStatus("Zlozone");
tracker.updateStatus("Wyslane");
tracker.updateStatus("Dostarczone");

class ApplicationContext {
    private static ApplicationContext instance;
    private ApplicationContext() {}
    static ApplicationContext getInstance() {
        if (instance == null) instance = new ApplicationContext();
        return instance;
    }
}

abstract class BaseController {
    final String handle(String path) {
        System.out.println("Przetwarzanie: " + path);
        return process(path);
    }
    abstract String process(String path);
}

class UsersController extends BaseController {
    String process(String path) { return "[\"Jan\", \"Ala\"]"; }
}

class ControllerFactory {
    static BaseController create(String path) {
        if (path.equals("/users")) return new UsersController();
        throw new IllegalArgumentException("Brak kontrolera dla " + path);
    }
}

abstract class Middleware {
    protected Middleware next;
    Middleware setNext(Middleware n) { this.next = n; return n; }
    abstract void handle(String path);
}

class LoggingMiddleware extends Middleware {
    void handle(String path) { System.out.println("Log: " + path); if (next != null) next.handle(path); }
}
class AuthMiddleware extends Middleware {
    void handle(String path) { System.out.println("Auth OK"); if (next != null) next.handle(path); }
}

ApplicationContext.getInstance();
Middleware chain = new LoggingMiddleware();
chain.setNext(new AuthMiddleware());
chain.handle("/users");

BaseController controller = ControllerFactory.create("/users");
System.out.println("Odpowiedz: " + controller.handle("/users"));
